namespace {const juce::Colour orange{0xffff8b32},bg{0xff17191c},panel{0xff24272c},text{0xfff4e8d8},muted{0xffa7a39d};
void labelStyle(juce::Label& label){label.setColour(juce::Label::textColourId,text);label.setFont(juce::Font(juce::FontOptions(13.0f)));}
void numeric(juce::Slider& s){s.setSliderStyle(juce::Slider::LinearBar);s.setTextBoxStyle(juce::Slider::TextBoxLeft,false,60,25);s.setNumDecimalPlacesToDisplay(2);}
void precision(juce::Slider& s,int places=2){s.textFromValueFunction=[places](double v){return juce::String(v,places);};s.valueFromTextFunction=[](const juce::String& t){return t.replaceCharacter(',','.').getDoubleValue();};s.updateText();}
}
OddLook::OddLook(){setColour(juce::ResizableWindow::backgroundColourId,bg);setColour(juce::Slider::thumbColourId,orange);setColour(juce::Slider::trackColourId,orange);setColour(juce::Slider::textBoxTextColourId,text);setColour(juce::Slider::textBoxBackgroundColourId,bg);setColour(juce::Slider::textBoxOutlineColourId,juce::Colours::transparentBlack);setColour(juce::TextButton::buttonColourId,juce::Colour(0xff37393c));setColour(juce::TextButton::buttonOnColourId,orange.darker(.4f));setColour(juce::TextButton::textColourOffId,text);setColour(juce::ToggleButton::textColourId,text);setColour(juce::ToggleButton::tickColourId,orange);setColour(juce::ComboBox::backgroundColourId,panel);setColour(juce::ComboBox::textColourId,text);setColour(juce::PopupMenu::backgroundColourId,panel);setColour(juce::PopupMenu::textColourId,text);setColour(juce::TabbedButtonBar::tabTextColourId,text);}
void OddLook::drawRotarySlider(juce::Graphics& g,int x,int y,int w,int h,float pos,float start,float end,juce::Slider&){
    auto bounds=juce::Rectangle<float>(static_cast<float>(x),static_cast<float>(y),static_cast<float>(w),static_cast<float>(h)).reduced(8);const float diameter=std::min(bounds.getWidth(),bounds.getHeight());bounds=bounds.withSizeKeepingCentre(diameter,diameter);const float radius=diameter*.5f;
    g.setColour(bg);g.fillEllipse(bounds);juce::Path arc;arc.addCentredArc(bounds.getCentreX(),bounds.getCentreY(),radius-2,radius-2,0,start,end,true);g.setColour(juce::Colour(0xff4d4540));g.strokePath(arc,juce::PathStrokeType(3));arc.clear();arc.addCentredArc(bounds.getCentreX(),bounds.getCentreY(),radius-2,radius-2,0,start,start+pos*(end-start),true);g.setColour(orange);g.strokePath(arc,juce::PathStrokeType(3));const float angle=start+pos*(end-start);g.drawLine(bounds.getCentreX()+std::sin(angle)*radius*.3f,bounds.getCentreY()-std::cos(angle)*radius*.3f,bounds.getCentreX()+std::sin(angle)*radius*.74f,bounds.getCentreY()-std::cos(angle)*radius*.74f,2);
}
