OddRoute::OddRoute(OddProcessor& p,size_t i):processor(p),index(i){
    for(auto* l:{&name,&liveValue}){addAndMakeVisible(*l);labelStyle(*l);}name.setText(OddProcessor::names[i],juce::dontSendNotification);liveValue.setColour(juce::Label::textColourId,orange);
    addAndMakeVisible(base);base.setSliderStyle(juce::Slider::LinearHorizontal);base.setTextBoxStyle(juce::Slider::TextBoxLeft,false,54,25);base.setNumDecimalPlacesToDisplay(2);base.onDragStart=[this]{processor.undoManager.beginNewTransaction("Ajustar timbre");};
    for(auto* s:{&low,&high}){addAndMakeVisible(*s);numeric(*s);s->onDragStart=[this]{processor.undoManager.beginNewTransaction("Limites de variacao");};}
    addAndMakeVisible(lock);baseA=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,OddProcessor::ids[i],base);lowA=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,OddProcessor::ids[i]+"Low",low);highA=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,OddProcessor::ids[i]+"High",high);lockA=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,OddProcessor::ids[i]+"Lock",lock);
    low.setTooltip("Limite inferior da variacao. Se os limites se cruzarem, os dois valores delimitam a mesma faixa.");high.setTooltip("Limite superior da variacao.");lock.setTooltip("Preserva o valor manual contra autonomia, variacao aleatoria, tensao e morph A/B.");liveValue.setTooltip("Valor que esta sendo ouvido agora.");
    lock.onClick=[this]{if(lock.getToggleState()&&processor.hasLiveValues.load())processor.setValue(OddProcessor::ids[index],processor.live[index].load());processor.state.copyState();};
    lock.setTooltip("Ao travar, guarda o valor ouvido agora e o protege da autonomia, Variar timbre, Tensao e morph A/B.");
    for(auto* control:{&base,&low,&high})precision(*control);
}
