OddSynthPanel::OddSynthPanel(OddProcessor& p):processor(p),amount(p,"amount","Quantidade"),rate(p,"rate","Movimento"){
    for(size_t i=0;i<routes.size();++i){routes[i]=std::make_unique<OddRoute>(p,i);addAndMakeVisible(*routes[i]);}
    for(auto* c:std::initializer_list<juce::Component*>{&mode,&amount,&rate,&freeze,&repeat,&random,&restart,&seed,&seedLabel,&help})addAndMakeVisible(*c);
    mode.addItemList({"Manual","Dentro dos limites","Livre"},1);modeA=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,"mode",mode);
    freezeA=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,"freeze",freeze);repeatA=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,"repeat",repeat);
    random.onClick=[this]{processor.randomise();};restart.onClick=[this]{processor.restart();};
    numeric(seed);seed.setNumDecimalPlacesToDisplay(0);seedA=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,"seed",seed);precision(seed,0);labelStyle(seedLabel);seedLabel.setText("Semente",juce::dontSendNotification);
    labelStyle(help);help.setFont(juce::Font(juce::FontOptions(12.0f)));help.setJustificationType(juce::Justification::topLeft);help.setColour(juce::Label::textColourId,muted);help.setText("Manual: sem movimento automatico.\nLimites: variacao suave.\nLivre: movimento irregular.\nFaixas e travas valem em ambos.",juce::dontSendNotification);
    freeze.setTooltip("Para o movimento dos controles no ponto atual. O som e os envelopes continuam tocando.");
}
