OddWave::OddWave(OddProcessor& p):processor(p){}
void OddWave::refresh(){auto next=processor.sampleCopy();if(next!=sample){sample=std::move(next);waveform.clear();if(sample&&!sample->left.empty()){const size_t points=std::min<size_t>(1600,sample->left.size());for(size_t k=0;k<points;++k){size_t lo=k*sample->left.size()/points,hi=std::max(lo+1,(k+1)*sample->left.size()/points);float max=0;for(size_t i=lo;i<hi;++i)max=std::max(max,std::abs(sample->left[i]));const float x=static_cast<float>(k)/static_cast<float>(std::max<size_t>(1,points-1));waveform.startNewSubPath(x,-max);waveform.lineTo(x,max);}}}repaint();}
void OddWave::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff101215));auto r=getLocalBounds().toFloat().reduced(8);if(!sample||sample->left.empty()){g.setColour(muted);g.drawFittedText("Arraste um arquivo de audio aqui\nou use Carregar audio",getLocalBounds().reduced(20),juce::Justification::centred,2);return;}
    const float a=processor.value("sampleStart"),b=processor.value("sampleEnd");g.setColour(orange.withAlpha(.17f));g.fillRect(juce::Rectangle<float>(r.getX()+std::min(a,b)*r.getWidth(),r.getY(),std::abs(a-b)*r.getWidth(),r.getHeight()));g.setColour(orange.withAlpha(.8f));g.strokePath(waveform,juce::PathStrokeType(1.0f),juce::AffineTransform::scale(r.getWidth(),-r.getHeight()*.43f).translated(r.getX(),r.getCentreY()));g.setColour(orange);g.drawVerticalLine(static_cast<int>(r.getX()+a*r.getWidth()),r.getY(),r.getBottom());g.drawVerticalLine(static_cast<int>(r.getX()+b*r.getWidth()),r.getY(),r.getBottom());}
void OddWave::mouseDown(const juce::MouseEvent& e){processor.undoManager.beginNewTransaction("Selecionar trecho");anchor=odd::unit((e.position.x-8)/std::max(1.0f,static_cast<float>(getWidth()-16)));select(anchor);}
void OddWave::mouseDrag(const juce::MouseEvent& e){select(odd::unit((e.position.x-8)/std::max(1.0f,static_cast<float>(getWidth()-16))));}
void OddWave::select(float b){processor.setValue("sampleStart",std::min(anchor,b));processor.setValue("sampleEnd",std::max(anchor,b));repaint();}
OddSamplePanel::OddSamplePanel(OddProcessor& p):processor(p),wave(p),sampleMix(p,"sampleMix","Sample"),speed(p,"sampleSpeed","Velocidade"),grain(p,"grain","Grao (s)"){
    for(auto* c:std::initializer_list<juce::Component*>{&wave,&sampleMix,&speed,&grain,&load,&save,&all,&preview,&status,&help,&granular,&loop,&reverse,&route,&start,&end,&startLabel,&endLabel})addAndMakeVisible(*c);
    const juce::StringArray names{"Reverse trecho","Manter trecho","Apagar trecho","Fade in","Fade out","Velocidade 0.5x","Velocidade 2x"};for(size_t i=0;i<edits.size();++i){addAndMakeVisible(edits[i]);edits[i].setButtonText(names[static_cast<int>(i)]);edits[i].onClick=[this,i]{if(!processor.sampleEdit(static_cast<int>(i)))juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::InfoIcon,"Samples","Carregue um sample e selecione um trecho. A edicao deve ficar abaixo de 8 milhoes de amostras por canal.");refresh();};}
    route.addItemList({"Destino: camada","Destino: Materia","Destino: Garganta","Destino: Enxame","Destino: Pulso"},1);routeA=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,"sampleRoute",route);route.setTooltip("Camada soma o sample aos motores. Outros destinos transformam o sample no motor escolhido; ajuste tambem o nivel desse motor.");
    load.onClick=[this]{choose(false);};save.onClick=[this]{choose(true);};all.onClick=[this]{processor.undoManager.beginNewTransaction("Selecionar tudo");processor.setValue("sampleStart",0);processor.setValue("sampleEnd",1);};
    preview.onClick=[this]{previewing=!previewing;if(previewing)processor.keyboard.noteOn(16,60,.7f);else processor.keyboard.noteOff(16,60,0);};
    granularA=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,"granular",granular);loopA=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,"sampleLoop",loop);reverseA=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,"sampleReverse",reverse);
    for(auto* s:{&start,&end}){numeric(*s);s->onDragStart=[this]{processor.undoManager.beginNewTransaction("Selecionar trecho");};}
    startA=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,"sampleStart",start);endA=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,"sampleEnd",end);
    for(auto* control:{&start,&end}){control->textFromValueFunction=[this](double v){auto s=processor.sampleCopy();const double duration=s?static_cast<double>(s->left.size())/s->sampleRate:1;return juce::String(v*duration,4)+" s";};control->valueFromTextFunction=[this](const juce::String& t){auto s=processor.sampleCopy();const double duration=s?static_cast<double>(s->left.size())/s->sampleRate:1;return duration>0?t.replaceCharacter(',','.').getDoubleValue()/duration:0;};control->updateText();}
    for(auto* l:{&status,&help,&startLabel,&endLabel})labelStyle(*l);startLabel.setText("Inicio",juce::dontSendNotification);endLabel.setText("Fim",juce::dontSendNotification);help.setColour(juce::Label::textColourId,muted);help.setText("Selecione arrastando na forma de onda. Edicoes podem ser desfeitas.\nVelocidade altera duracao e afinacao; MIDI 60 reproduz na altura original.\nGranular reorganiza o trecho em graos. O sample fica salvo com o preset/projeto.",juce::dontSendNotification);help.setJustificationType(juce::Justification::topLeft);help.setFont(juce::Font(juce::FontOptions(12.0f)));refresh();
}
OddSamplePanel::~OddSamplePanel(){if(previewing)processor.keyboard.noteOff(16,60,0);}
bool OddSamplePanel::isInterestedInFileDrag(const juce::StringArray& files){return files.size()==1;}
void OddSamplePanel::filesDropped(const juce::StringArray& files,int,int){if(files.size()==1)importFile(juce::File(files[0]));}
void OddSamplePanel::importFile(const juce::File& file){juce::String error;if(!processor.loadSample(file,error))juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"Samples",error);else{previewing=false;refresh();}}
void OddSamplePanel::choose(bool exporting){chooser=std::make_unique<juce::FileChooser>(exporting?"Exportar sample editado":"Carregar audio",juce::File{},exporting?"*.wav":"*.wav;*.aif;*.aiff;*.flac;*.ogg;*.mp3");const int flags=exporting?(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting):(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles);auto safe=juce::Component::SafePointer<OddSamplePanel>(this);chooser->launchAsync(flags,[safe,exporting](const juce::FileChooser& fc){if(!safe)return;auto file=fc.getResult();if(file==juce::File{})return;if(exporting){if(!safe->processor.exportSample(file.withFileExtension("wav")))safe->status.setText("Nao foi possivel exportar o sample.",juce::dontSendNotification);}else safe->importFile(file);});}
void OddSamplePanel::paint(juce::Graphics& g){g.fillAll(bg);}
