void OddSamplePanel::refresh(){wave.refresh();auto s=processor.sampleCopy();if(s)status.setText(processor.sampleName()+"  |  "+juce::String(static_cast<double>(s->left.size())/s->sampleRate,2)+" s",juce::dontSendNotification);else status.setText("Sem sample",juce::dontSendNotification);start.updateText();end.updateText();save.setEnabled(s&&!s->left.empty());preview.setEnabled(s&&!s->left.empty());for(auto& e:edits)e.setEnabled(s&&!s->left.empty());}
OddEditor::OddEditor(OddProcessor& p):AudioProcessorEditor(p),processor(p),synth(p),samples(p),keyboard(p.keyboard,juce::MidiKeyboardComponent::horizontalKeyboard){
    setLookAndFeel(&look);setOpaque(true);
    for(auto* c:std::initializer_list<juce::Component*>{&tabs,&presets,&undo,&redo,&save,&load,&capture,&panic,&storeA,&storeB,&recallA,&recallB,&morph,&morphLabel,&meter,&keyboard})addAndMakeVisible(*c);
    tabs.addTab("INSTRUMENTO",panel,&synth,false);tabs.addTab("SAMPLES",panel,&samples,false);tabs.setTabBarDepth(34);
    const std::array<juce::String,4> sourceIds{{"material","throat","swarm","pulse"}},sourceNames{{"MATERIA","GARGANTA","ENXAME","PULSO"}};
    for(size_t i=0;i<sources.size();++i){sources[i]=std::make_unique<OddKnob>(p,sourceIds[i],sourceNames[i]);addAndMakeVisible(*sources[i]);}
    const std::array<juce::String,7> bottomIds{{"tension","attack","release","reverb","delay","drive","gain"}},bottomNames{{"Tensao / CC1","Ataque (s)","Release (s)","Reverb","Delay","Distorcao","Saida (dB)"}};
    for(size_t i=0;i<bottom.size();++i){bottom[i]=std::make_unique<OddKnob>(p,bottomIds[i],bottomNames[i]);addAndMakeVisible(*bottom[i]);}
    presets.addItemList({"Inicial / seco","Metal tensionado","Garganta incerta","Enxame lento","Pulso organico","Convergencia"},1);presets.setTextWhenNothingSelected("Presets de fabrica");presets.onChange=[this]{processor.factoryPreset(presets.getSelectedItemIndex());};
    undo.onClick=[this]{processor.state.copyState();processor.undoManager.undo();};redo.onClick=[this]{processor.undoManager.redo();};save.onClick=[this]{fileAction(0);};load.onClick=[this]{fileAction(1);};capture.onClick=[this]{fileAction(2);};panic.onClick=[this]{processor.panic();};panic.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff813f23));
    storeA.onClick=[this]{processor.captureSlot(0);};storeB.onClick=[this]{processor.captureSlot(1);};recallA.onClick=[this]{processor.recallSlot(0);};recallB.onClick=[this]{processor.recallSlot(1);};
    numeric(morph);morph.setSliderStyle(juce::Slider::LinearHorizontal);morph.setTextBoxStyle(juce::Slider::TextBoxRight,false,56,24);morph.setRange(0,1,.001);morph.setValue(0);morph.onDragStart=[this]{processor.undoManager.beginNewTransaction("Morph A B");};morph.onValueChange=[this]{processor.morph(static_cast<float>(morph.getValue()));};labelStyle(morphLabel);morphLabel.setText("A  < Morph >  B",juce::dontSendNotification);labelStyle(meter);meter.setJustificationType(juce::Justification::centredRight);
    capture.setTooltip("Exporta os ultimos 15 segundos de audio, incluindo os efeitos e movimentos ouvidos.");storeA.setTooltip("Guarda o estado completo, com sample. Salvo junto com o projeto.");storeB.setTooltip("Guarda uma segunda alternativa completa.");morph.setTooltip("Interpola os seis controles e os niveis dos motores entre A e B. Parametros travados sao preservados. Samples e efeitos nao sao interpolados.");
    setResizable(true,true);setResizeLimits(1050,880,1600,1300);setSize(1160,920);timerCallback();startTimerHz(15);
}
