void OddEditor::timerCallback(){synth.refresh();samples.refresh();undo.setEnabled(processor.undoManager.canUndo());redo.setEnabled(processor.undoManager.canRedo());recallA.setEnabled(processor.hasSlot(0));recallB.setEnabled(processor.hasSlot(1));morph.setEnabled(processor.hasSlot(0)&&processor.hasSlot(1));const float peak=processor.peak.load();meter.setText(juce::String(processor.voices.load())+" vozes | "+juce::String(juce::Decibels::gainToDecibels(peak,-90.0f),1)+" dB",juce::dontSendNotification);}
void OddEditor::fileAction(int action){const bool opening=action==1;chooser=std::make_unique<juce::FileChooser>(action==2?"Guardar audio recente":opening?"Abrir preset":"Salvar preset",juce::File{},action==2?"*.wav":"*.oddpreset");const int flags=(opening?juce::FileBrowserComponent::openMode:juce::FileBrowserComponent::saveMode)|juce::FileBrowserComponent::canSelectFiles|(opening?0:juce::FileBrowserComponent::warnAboutOverwriting);auto safe=juce::Component::SafePointer<OddEditor>(this);chooser->launchAsync(flags,[safe,action](const juce::FileChooser& fc){if(!safe)return;auto file=fc.getResult();if(file==juce::File{})return;bool ok=false;if(action==0)ok=safe->processor.savePreset(file.withFileExtension("oddpreset"));if(action==1)ok=safe->processor.loadPreset(file);if(action==2)ok=safe->processor.exportCapture(file.withFileExtension("wav"));if(!ok)juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"OddSynth","Nao foi possivel concluir. Para capturar audio, toque o instrumento primeiro.");});}
